// Package fixtures defines TxShield's security test scenarios: malicious and
// benign transactions (including false-positive cases) with the chain facts,
// reputation data, and simulation results needed to analyze them
// deterministically, plus the expected outcome.
//
// Scenario JSON files live in tests/fixtures/scenarios and are generated by
// `go run ./tests/fixtures/gen` so that calldata is always correctly
// ABI-encoded. They are test fixtures, never production data: addresses,
// balances, and simulation results are synthetic.
package fixtures

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"

	"github.com/txshield/txshield/pkg/models"
)

// Scenario is one fixture.
type Scenario struct {
	Name              string                    `json:"name"`
	Description       string                    `json:"description"`
	Kind              string                    `json:"kind"` // "malicious" or "benign"
	FalsePositiveCase bool                      `json:"falsePositiveCase,omitempty"`
	Tx                models.TransactionRequest `json:"tx"`
	ABI               json.RawMessage           `json:"abi,omitempty"`
	// Contracts are on-chain facts served by a fake inspector. When empty,
	// the scenario runs without chain access (ContractsKnown=false).
	Contracts []models.ContractInfo `json:"contracts,omitempty"`
	// Reputation records served by a list provider named "fixture".
	Reputation []models.ReputationRecord `json:"reputation,omitempty"`
	// Simulation is returned by a fake simulator. When nil, no simulation runs.
	Simulation *models.SimulationResult `json:"simulation,omitempty"`
	Expect     Expect                   `json:"expect"`
}

// Expect is the asserted outcome.
type Expect struct {
	Rules       []string            `json:"rules,omitempty"`       // must fire
	AbsentRules []string            `json:"absentRules,omitempty"` // must not fire
	MinScore    int                 `json:"minScore"`
	MaxScore    int                 `json:"maxScore"`
	Category    models.RiskCategory `json:"category,omitempty"`
	Verdict     string              `json:"verdict,omitempty"`
}

// Dir returns the scenarios directory.
func Dir() string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "scenarios")
}

// Load reads all scenarios in Dir, sorted by name.
func Load() ([]Scenario, error) {
	paths, err := filepath.Glob(filepath.Join(Dir(), "*.json"))
	if err != nil {
		return nil, err
	}
	sort.Strings(paths)
	out := make([]Scenario, 0, len(paths))
	for _, p := range paths {
		b, err := os.ReadFile(p) //nolint:gosec // fixed fixtures directory
		if err != nil {
			return nil, err
		}
		var s Scenario
		if err := json.Unmarshal(b, &s); err != nil {
			return nil, fmt.Errorf("%s: %w", p, err)
		}
		out = append(out, s)
	}
	return out, nil
}
